def parse_duration(s: str) -> int:
    parts = s.split()
    if len(parts) == 1:
        return _parse_single_part(parts[0])
    else:
        return _parse_multiple_parts(parts)

def _parse_single_part(part):
    if part[-1] in ['h', 'm', 's']:
        return int(part[:-1]) * {'h': 3600, 'm': 60, 's': 1}[part[-1]]
    else:
        raise ValueError(f"Invalid duration: {part}")

def _parse_multiple_parts(parts):
    total = 0
    for part in parts:
        if part[-1] == 'h':
            total += int(part[:-1]) * 3600
        elif part[-1] == 'm':
            total += int(part[:-1]) * 60
        else:  # s
            total += int(part)
    return total

# Example usage:
