import re

def is_valid_ipv4(s: str) -> bool:
    if not isinstance(s, str):
        return False

    # Check for spaces or empty string
    if ' ' in s or len(s) == 0:
        return False

    # Split by dots
    parts = s.split('.')

    # Must have exactly 4 parts
    if len(parts) != 4:
        return False

    for part in parts:
        # Check for leading zeros (except for "0" itself)
        if len(part) > 1 and part[0] == '0':
            return False

        # Check if all characters are digits
        if not part.isdigit():
            return False

        # Check range 0-255
        num = int(part)
        if num < 0 or num > 255:
            return False

    return True
```

